CREATE TABLE campus(id bigint PRIMARY KEY AUTO_INCREMENT,name varchar(80) NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT true);
INSERT INTO campus(id,name) VALUES(1,'默认校区');
CREATE TABLE store(id bigint PRIMARY KEY AUTO_INCREMENT,campus_id bigint NOT NULL,name varchar(80) NOT NULL,enabled boolean NOT NULL DEFAULT true,open boolean NOT NULL DEFAULT false,delivery_fee decimal(10,2) NOT NULL DEFAULT 6,packaging_fee decimal(10,2) NOT NULL DEFAULT 1,hours varchar(500) NOT NULL DEFAULT '["00:00-24:00"]',phone varchar(20) NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 0,UNIQUE KEY uq_store_name(campus_id,name));
INSERT INTO store(id,campus_id,name,open,delivery_fee,packaging_fee,hours,phone,version) SELECT 1,1,'默认店铺',open,delivery_fee,packaging_fee,hours,phone,version FROM shop_settings WHERE id=1;
ALTER TABLE employee MODIFY role varchar(24) NOT NULL,ADD store_id bigint NULL,ADD campus_id bigint NULL;
UPDATE employee SET role='PLATFORM_ADMIN' WHERE role='ADMIN';
UPDATE employee SET store_id=1,campus_id=1 WHERE role='OPERATOR';
UPDATE employee SET campus_id=1 WHERE role='DELIVERER';
UPDATE auth_session SET revoked=true WHERE subject_type='ADMIN';
ALTER TABLE campus_building DROP INDEX name,ADD campus_id bigint NOT NULL DEFAULT 1,ADD UNIQUE KEY uq_building_name(campus_id,name);
ALTER TABLE category DROP INDEX idx_category_name,ADD store_id bigint NOT NULL DEFAULT 1,ADD UNIQUE KEY uq_category_store(store_id,name);
ALTER TABLE dish DROP INDEX idx_dish_name,ADD store_id bigint NOT NULL DEFAULT 1,ADD UNIQUE KEY uq_dish_store(store_id,name);
ALTER TABLE setmeal DROP INDEX idx_setmeal_name,ADD store_id bigint NOT NULL DEFAULT 1,ADD UNIQUE KEY uq_setmeal_store(store_id,name);
CREATE TABLE checkout(id bigint PRIMARY KEY AUTO_INCREMENT,user_id bigint NOT NULL,request_id varchar(36) NOT NULL,request_hash char(64) NOT NULL,state varchar(16) NOT NULL,total_cents bigint NOT NULL,paid_at datetime NULL,expires_at datetime NOT NULL,created_at datetime NOT NULL,version bigint NOT NULL DEFAULT 0,quote_json mediumtext NOT NULL,UNIQUE KEY uq_checkout_request(user_id,request_id),KEY ix_checkout_expiry(state,expires_at));
ALTER TABLE orders ADD store_id bigint NOT NULL DEFAULT 1,ADD campus_id bigint NOT NULL DEFAULT 1,ADD checkout_id bigint NULL,ADD fulfillment varchar(16) NOT NULL DEFAULT 'DELIVERY',ADD ready boolean NOT NULL DEFAULT false,ADD completed_at datetime NULL,ADD paid_cents bigint NOT NULL DEFAULT 0,ADD refunded_cents bigint NOT NULL DEFAULT 0,ADD reserved_refund_cents bigint NOT NULL DEFAULT 0,ADD shop_discount_cents bigint NOT NULL DEFAULT 0,ADD platform_discount_cents bigint NOT NULL DEFAULT 0,ADD pickup_hash char(64) NULL,ADD pickup_code varchar(12) NULL,ADD pickup_attempts int NOT NULL DEFAULT 0,ADD KEY ix_orders_store(store_id,order_time,id),ADD KEY ix_orders_checkout(checkout_id);
INSERT INTO checkout(id,user_id,request_id,request_hash,state,total_cents,paid_at,expires_at,created_at,quote_json)
 SELECT id,user_id,COALESCE(request_id,CONCAT('legacy-',id)),COALESCE(request_hash,REPEAT('0',64)),CASE WHEN pay_status<>0 THEN 'PAID' WHEN status=1 THEN 'PENDING' ELSE 'CANCELLED' END,ROUND(amount*100),CASE WHEN pay_status<>0 THEN COALESCE(checkout_time,order_time) ELSE NULL END,COALESCE(pay_expires_at,DATE_ADD(order_time,INTERVAL 15 MINUTE)),order_time,'{}' FROM orders;
UPDATE orders SET checkout_id=id,paid_cents=CASE WHEN pay_status<>0 THEN ROUND(amount*100) ELSE 0 END,refunded_cents=CASE WHEN pay_status=2 THEN ROUND(amount*100) ELSE 0 END,completed_at=CASE WHEN status=5 THEN COALESCE(delivery_time,order_time) ELSE NULL END;
ALTER TABLE order_detail ADD line_total_cents bigint NOT NULL DEFAULT 0,ADD refunded_quantity int NOT NULL DEFAULT 0,ADD reserved_quantity int NOT NULL DEFAULT 0;
UPDATE order_detail SET line_total_cents=ROUND(amount*number*100);
CREATE TABLE store_cart_state(user_id bigint NOT NULL,store_id bigint NOT NULL,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(user_id,store_id));
CREATE TABLE store_cart_item(id bigint PRIMARY KEY AUTO_INCREMENT,user_id bigint NOT NULL,store_id bigint NOT NULL,item_type varchar(8) NOT NULL,item_id bigint NOT NULL,flavors varchar(1000) NOT NULL,flavor_hash char(64) NOT NULL,quantity int NOT NULL,CHECK(quantity BETWEEN 1 AND 50),UNIQUE KEY uq_store_cart(user_id,store_id,item_type,item_id,flavor_hash));
INSERT INTO store_cart_state SELECT user_id,1,version FROM cart_state;
INSERT INTO store_cart_item(user_id,store_id,item_type,item_id,flavors,flavor_hash,quantity) SELECT user_id,1,item_type,item_id,flavors,flavor_hash,quantity FROM cart_item;
CREATE TABLE promotion(id bigint PRIMARY KEY AUTO_INCREMENT,store_id bigint NOT NULL,item_type varchar(8) NOT NULL,item_id bigint NOT NULL,price_cents bigint NOT NULL,starts_at datetime NOT NULL,ends_at datetime NOT NULL,enabled boolean NOT NULL DEFAULT true,KEY ix_promotion_item(store_id,item_type,item_id,starts_at));
CREATE TABLE coupon(id bigint PRIMARY KEY AUTO_INCREMENT,store_id bigint NULL,name varchar(80) NOT NULL,kind varchar(16) NOT NULL,threshold_cents bigint NOT NULL,value bigint NOT NULL,cap_cents bigint NULL,total int NOT NULL,claimed int NOT NULL DEFAULT 0,per_user int NOT NULL,starts_at datetime NOT NULL,ends_at datetime NOT NULL,enabled boolean NOT NULL DEFAULT true,CHECK(total>=claimed),CHECK(claimed>=0));
CREATE TABLE user_coupon(id bigint PRIMARY KEY AUTO_INCREMENT,user_id bigint NOT NULL,coupon_id bigint NOT NULL,state varchar(16) NOT NULL DEFAULT 'AVAILABLE',checkout_id bigint NULL,KEY ix_coupon_user(user_id,coupon_id,state));
CREATE TABLE delivery_task(id bigint PRIMARY KEY AUTO_INCREMENT,order_id bigint NOT NULL UNIQUE,campus_id bigint NOT NULL,courier_id bigint NULL,state varchar(16) NOT NULL DEFAULT 'OPEN',version bigint NOT NULL DEFAULT 0,KEY ix_delivery_pool(campus_id,state));
CREATE TABLE aftersale(id bigint PRIMARY KEY AUTO_INCREMENT,order_id bigint NOT NULL,user_id bigint NOT NULL,store_id bigint NOT NULL,kind varchar(16) NOT NULL,state varchar(24) NOT NULL,reason varchar(200) NOT NULL,decision varchar(200) NULL,amount_cents bigint NOT NULL,fee_cents bigint NOT NULL DEFAULT 0,appealed boolean NOT NULL DEFAULT false,created_at datetime NOT NULL,version bigint NOT NULL DEFAULT 0,KEY ix_aftersale_order(order_id,state));
CREATE TABLE aftersale_item(request_id bigint NOT NULL,detail_id bigint NOT NULL,quantity int NOT NULL,amount_cents bigint NOT NULL,PRIMARY KEY(request_id,detail_id));
CREATE TABLE refund_request(id bigint PRIMARY KEY AUTO_INCREMENT,order_id bigint NOT NULL,aftersale_id bigint NULL UNIQUE,store_id bigint NOT NULL,amount_cents bigint NOT NULL,state varchar(16) NOT NULL DEFAULT 'REQUESTED',attempts int NOT NULL DEFAULT 0,next_attempt_at datetime NOT NULL,lease_until datetime NULL,lease_token varchar(36) NULL,last_error varchar(80) NULL,created_at datetime NOT NULL,UNIQUE KEY uq_refund_legacy(order_id,aftersale_id),KEY ix_refund_request_due(state,next_attempt_at));
INSERT INTO refund_request(id,order_id,store_id,amount_cents,state,attempts,next_attempt_at,lease_until,lease_token,last_error,created_at) SELECT r.id,r.order_id,1,ROUND(o.amount*100),r.state,r.attempts,r.next_attempt_at,r.lease_until,r.lease_token,r.last_error,r.created_at FROM refund_task r JOIN orders o ON o.id=r.order_id;
UPDATE orders o JOIN refund_request r ON r.order_id=o.id SET o.reserved_refund_cents=r.amount_cents WHERE r.state<>'SUCCEEDED';
UPDATE refund_task SET state='MIGRATED',lease_until=NULL,lease_token=NULL;
CREATE TABLE evidence(id varchar(36) PRIMARY KEY,user_id bigint NOT NULL,order_id bigint NOT NULL,request_id bigint NULL,path varchar(100) NOT NULL,created_at datetime NOT NULL);
ALTER TABLE refund_request ADD succeeded_at datetime NULL;
UPDATE refund_request SET succeeded_at=created_at WHERE state='SUCCEEDED';
CREATE TABLE favorite(user_id bigint NOT NULL,target_type varchar(8) NOT NULL,target_id bigint NOT NULL,store_id bigint NOT NULL,PRIMARY KEY(user_id,target_type,target_id,store_id));
CREATE TABLE review(id bigint PRIMARY KEY AUTO_INCREMENT,order_id bigint NOT NULL UNIQUE,user_id bigint NOT NULL,store_id bigint NOT NULL,rating int NOT NULL,content varchar(1000) NOT NULL,reply varchar(1000) NULL,hidden boolean NOT NULL DEFAULT false,hide_reason varchar(200) NULL,created_at datetime NOT NULL,CHECK(rating BETWEEN 1 AND 5));
ALTER TABLE audit_log ADD store_id bigint NULL,ADD campus_id bigint NULL;
